('RSK-GAGAL-PANEN','Risiko / Kerugian','Produksi','Risiko Gagal Panen','risiko-gagal-panen',NULL,'padi,jagung,kedelai','Semua fase','risiko','catatan_risiko','rupiah',NULL,NULL,'INPUT_MANUAL','Katalog risiko/kerugian menekankan pencatatan estimasi dampak.','AGROTRACK_KATALOG_RISIKO_KERUGIAN_PADI_JAGUNG_KEDELAI.md','2026-06-16','Mencatat potensi kerugian karena gagal panen.','Dipakai sebagai risk register, bukan biaya otomatis.','Kerugian baru memengaruhi analisis jika benar terjadi dan dicatat.',''),
